mapper.select:
/*selectMasterMpRqBulkQuotationProjectList*/ SELECT * FROM ( SELECT TO_CHAR(ADD_DATE, 'YYYYMMDD') AS ADD_DATE, PROJECT_START_DATE, PROJECT_END_DATE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ01' AND CODE = PROJECT_TYPE AND FLAG = 'Y') AS PROJECT_TYPE, BURQ_NO, PROJECT_NAME, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = 'KRKORE0001' AND CODE = KEP_DEPT AND FLAG = 'Y') AS KEP_DEPT, TOTAL_ITEM_CNT, TOTAL_AMT, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PROJECT_MNG_USER) AS PM_NAME, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ02' AND CODE = PROJECT_STATUS) AS PROJECT_STATUS, PROJECT_STATUS AS PROJECT_STATUS_CODE, TO_CHAR(SG_START_DATE,'YYYY/MM/DD') AS SG_START_DATE, TO_CHAR(RFQ_START_DATE,'YYYY/MM/DD') AS RFQ_START_DATE, TO_CHAR(RFQ_END_DATE,'YYYY/MM/DD') AS RFQ_END_DATE, TO_CHAR(RFQ_MERGE_DATE,'YYYY/MM/DD') AS RFQ_MERGE_DATE, TO_CHAR(RFQ_SUBMIT_DATE,'YYYY/MM/DD') AS RFQ_SUBMIT_DATE, TO_CHAR(RFQ_APPROVAL_DATE,'YYYY/MM/DD') AS RFQ_APPROVAL_DATE, SG_START_SCHD_DATE AS SG_START_DATE_SCHD, RFQ_START_SCHD_DATE AS RFQ_START_DATE_SCHD, RFQ_END_SCHD_DATE AS RFQ_END_DATE_SCHD, RFQ_MERGE_SCHD_DATE AS RFQ_MERGE_DATE_SCHD, RFQ_SUBMIT_SCHD_DATE AS RFQ_SUBMIT_DATE_SCHD, RFQ_APPROVAL_SCHD_DATE AS RFQ_APPROVAL_DATE_SCHD FROM KEP_BURQ_MNG WHERE 1=1
AND TO_CHAR(ADD_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND PROJECT_START_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PROJECT_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}
) WHERE 1=1
AND UPPER(PROJECT_NAME) LIKE UPPER('%'||#{st_project_input}||'%')
AND BURQ_NO = #{st_project_input}
AND KEP_DEPT IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ06' AND CODE IN
#{dept}
AND FLAG = 'Y')
AND PROJECT_TYPE = #{st_project_type}
AND UPPER(PM_NAME) LIKE UPPER('%'||#{st_project_mng_user}||'%')
AND PROJECT_STATUS IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ02' AND CODE IN
#{status}
AND FLAG = 'Y')
AND PROJECT_STATUS IN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ02' AND FLAG = 'Y' AND TEXT4 = 'Y')
ORDER BY PROJECT_START_DATE

mapper.update:

/* abortBulkQuotation */
UPDATE KEP_BURQ_MNG
SET PROJECT_STATUS = 'G',
	ABORT_DATE = SYSDATE,
	ABORT_REASON = #{st_abort_reason},
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{st_user_id}
WHERE BURQ_NO = #{st_burq_no}
AND PROJECT_STATUS <> 'G'


/* abortBulkQuotationRFQ */
UPDATE KEP_BURQ_RFQ
SET STATUS = 'K4',
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{st_user_id}
WHERE BURQ_NO = #{st_burq_no}

mapper.select:
/*selectMasterMpRqBulkQuotationProjectCnt*/ SELECT COUNT(*) FROM KEP_BURQ_MNG WHERE RFQ_END_DATE < SYSDATE
AND TO_CHAR(ADD_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND PROJECT_START_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PROJECT_END_DATE BETWEEN #{st_from_date} AND #{st_to_date}

mapper.update:
